139	/* HELLOTYPE.RANGE key first count */
140	int HelloTypeRange_RedisCommand(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
141	    RedisModule_AutoMemory(ctx); /* Use automatic memory management. */
142	
143	    if (argc != 4) return RedisModule_WrongArity(ctx);
144	    RedisModuleKey *key = RedisModule_OpenKey(ctx,argv[1],
145	        REDISMODULE_READ|REDISMODULE_WRITE);
146	    int type = RedisModule_KeyType(key);
147	    if (type != REDISMODULE_KEYTYPE_EMPTY &&
148	        RedisModule_ModuleTypeGetType(key) != HelloType)
149	    {
150	        return RedisModule_ReplyWithError(ctx,REDISMODULE_ERRORMSG_WRONGTYPE);
151	    }
152	
153	    long long first, count;
154	    if (RedisModule_StringToLongLong(argv[2],&first) != REDISMODULE_OK ||
155	        RedisModule_StringToLongLong(argv[3],&count) != REDISMODULE_OK ||
156	        first < 0 || count < 0)
157	    {
158	        return RedisModule_ReplyWithError(ctx,
159	            "ERR invalid first or count parameters");
160	    }
161	
162	    struct HelloTypeObject *hto = RedisModule_ModuleTypeGetValue(key);
163	    struct HelloTypeNode *node = hto ? hto->head : NULL;
164	    RedisModule_ReplyWithArray(ctx,REDISMODULE_POSTPONED_LEN);
165	    long long arraylen = 0;
166	    while(node && count--) {
167	        RedisModule_ReplyWithLongLong(ctx,node->value);
168	        arraylen++;
169	        node = node->next;
170	    }
171	    RedisModule_ReplySetArrayLength(ctx,arraylen);
172	    return REDISMODULE_OK;
173	}
