175	/* HELLOTYPE.LEN key */
176	int HelloTypeLen_RedisCommand(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
177	    RedisModule_AutoMemory(ctx); /* Use automatic memory management. */
178	
179	    if (argc != 2) return RedisModule_WrongArity(ctx);
180	    RedisModuleKey *key = RedisModule_OpenKey(ctx,argv[1],
181	        REDISMODULE_READ|REDISMODULE_WRITE);
