186	        return RedisModule_ReplyWithError(ctx,REDISMODULE_ERRORMSG_WRONGTYPE);
187	    }
188	
189	    struct HelloTypeObject *hto = RedisModule_ModuleTypeGetValue(key);
190	    RedisModule_ReplyWithLongLong(ctx,hto ? hto->len : 0);
191	    return REDISMODULE_OK;
192	}
