196	/* Reply callback for blocking command HELLOTYPE.BRANGE, this will get
197	 * called when the key we blocked for is ready: we need to check if we
198	 * can really serve the client, and reply OK or ERR accordingly. */
199	int HelloBlock_Reply(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
200	    REDISMODULE_NOT_USED(argv);
201	    REDISMODULE_NOT_USED(argc);
202	
203	    RedisModuleString *keyname = RedisModule_GetBlockedClientReadyKey(ctx);
204	    RedisModuleKey *key = RedisModule_OpenKey(ctx,keyname,REDISMODULE_READ);
205	    int type = RedisModule_KeyType(key);
206	    if (type != REDISMODULE_KEYTYPE_MODULE ||
207	        RedisModule_ModuleTypeGetType(key) != HelloType)
208	    {
209	        RedisModule_CloseKey(key);
210	        return REDISMODULE_ERR;
211	    }
212	
213	    /* In case the key is able to serve our blocked client, let's directly
214	     * use our original command implementation to make this example simpler. */
215	    RedisModule_CloseKey(key);
216	    return HelloTypeRange_RedisCommand(ctx,argv,argc-1);
217	}
