219	/* Timeout callback for blocking command HELLOTYPE.BRANGE */
220	int HelloBlock_Timeout(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
221	    REDISMODULE_NOT_USED(argv);
222	    REDISMODULE_NOT_USED(argc);
223	    return RedisModule_ReplyWithSimpleString(ctx,"Request timedout");
224	}
