226	/* Private data freeing callback for HELLOTYPE.BRANGE command. */
227	void HelloBlock_FreeData(RedisModuleCtx *ctx, void *privdata) {
228	    REDISMODULE_NOT_USED(ctx);
229	    RedisModule_Free(privdata);
230	}
