232	/* HELLOTYPE.BRANGE key first count timeout -- This is a blocking version of
233	 * the RANGE operation, in order to show how to use the API
234	 * RedisModule_BlockClientOnKeys(). */
235	int HelloTypeBRange_RedisCommand(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
236	    if (argc != 5) return RedisModule_WrongArity(ctx);
237	    RedisModule_AutoMemory(ctx); /* Use automatic memory management. */
238	    RedisModuleKey *key = RedisModule_OpenKey(ctx,argv[1],
239	        REDISMODULE_READ|REDISMODULE_WRITE);
240	    int type = RedisModule_KeyType(key);
241	    if (type != REDISMODULE_KEYTYPE_EMPTY &&
242	        RedisModule_ModuleTypeGetType(key) != HelloType)
243	    {
244	        return RedisModule_ReplyWithError(ctx,REDISMODULE_ERRORMSG_WRONGTYPE);
245	    }
246	
247	    /* Parse the timeout before even trying to serve the client synchronously,
248	     * so that we always fail ASAP on syntax errors. */
249	    long long timeout;
250	    if (RedisModule_StringToLongLong(argv[4],&timeout) != REDISMODULE_OK) {
251	        return RedisModule_ReplyWithError(ctx,
252	            "ERR invalid timeout parameter");
253	    }
254	
255	    /* Can we serve the reply synchronously? */
256	    if (type != REDISMODULE_KEYTYPE_EMPTY) {
257	        return HelloTypeRange_RedisCommand(ctx,argv,argc-1);
258	    }
259	
260	    /* Otherwise let's block on the key. */
261	    void *privdata = RedisModule_Alloc(100);
262	    RedisModule_BlockClientOnKeys(ctx,HelloBlock_Reply,HelloBlock_Timeout,HelloBlock_FreeData,timeout,argv+1,1,privdata);
263	    return REDISMODULE_OK;
264	}
