266	/* ========================== "hellotype" type methods ======================= */
267	
268	void *HelloTypeRdbLoad(RedisModuleIO *rdb, int encver) {
269	    if (encver != 0) {
270	        /* RedisModule_Log("warning","Can't load data with version %d", encver);*/
271	        return NULL;
272	    }
273	    uint64_t elements = RedisModule_LoadUnsigned(rdb);
274	    struct HelloTypeObject *hto = createHelloTypeObject();
275	    while(elements--) {
276	        int64_t ele = RedisModule_LoadSigned(rdb);
277	        HelloTypeInsert(hto,ele);
278	    }
279	    return hto;
280	}
281	
282	void HelloTypeRdbSave(RedisModuleIO *rdb, void *value) {
283	    struct HelloTypeObject *hto = value;
284	    struct HelloTypeNode *node = hto->head;
285	    RedisModule_SaveUnsigned(rdb,hto->len);
286	    while(node) {
287	        RedisModule_SaveSigned(rdb,node->value);
288	        node = node->next;
289	    }
290	}
291	
292	void HelloTypeAofRewrite(RedisModuleIO *aof, RedisModuleString *key, void *value) {
293	    struct HelloTypeObject *hto = value;
294	    struct HelloTypeNode *node = hto->head;
295	    while(node) {
296	        RedisModule_EmitAOF(aof,"HELLOTYPE.INSERT","sl",key,node->value);
297	        node = node->next;
298	    }
299	}
300	
301	/* The goal of this function is to return the amount of memory used by
302	 * the HelloType value. */
303	size_t HelloTypeMemUsage(const void *value) {
304	    const struct HelloTypeObject *hto = value;
305	    struct HelloTypeNode *node = hto->head;
306	    return sizeof(*hto) + sizeof(*node)*hto->len;
307	}
308	
309	void HelloTypeFree(void *value) {
310	    HelloTypeReleaseObject(value);
311	}
312	
313	void HelloTypeDigest(RedisModuleDigest *md, void *value) {
314	    struct HelloTypeObject *hto = value;
315	    struct HelloTypeNode *node = hto->head;
316	    while(node) {
317	        RedisModule_DigestAddLongLong(md,node->value);
318	        node = node->next;
319	    }
320	    RedisModule_DigestEndSequence(md);
321	}
322	
323	/* This function must be present on each Redis module. It is used in order to
324	 * register the commands into the Redis server. */
325	int RedisModule_OnLoad(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
326	    REDISMODULE_NOT_USED(argv);
327	    REDISMODULE_NOT_USED(argc);
328	
329	    if (RedisModule_Init(ctx,"hellotype",1,REDISMODULE_APIVER_1)
330	        == REDISMODULE_ERR) return REDISMODULE_ERR;
331	
332	    RedisModuleTypeMethods tm = {
333	        .version = REDISMODULE_TYPE_METHOD_VERSION,
334	        .rdb_load = HelloTypeRdbLoad,
335	        .rdb_save = HelloTypeRdbSave,
336	        .aof_rewrite = HelloTypeAofRewrite,
337	        .mem_usage = HelloTypeMemUsage,
338	        .free = HelloTypeFree,
339	        .digest = HelloTypeDigest
340	    };
341	
342	    HelloType = RedisModule_CreateDataType(ctx,"hellotype",0,&tm);
343	    if (HelloType == NULL) return REDISMODULE_ERR;
344	
345	    if (RedisModule_CreateCommand(ctx,"hellotype.insert",
346	        HelloTypeInsert_RedisCommand,"write deny-oom",1,1,1) == REDISMODULE_ERR)
347	        return REDISMODULE_ERR;
348	
349	    if (RedisModule_CreateCommand(ctx,"hellotype.range",
350	        HelloTypeRange_RedisCommand,"readonly",1,1,1) == REDISMODULE_ERR)
351	        return REDISMODULE_ERR;
352	
353	    if (RedisModule_CreateCommand(ctx,"hellotype.len",
354	        HelloTypeLen_RedisCommand,"readonly",1,1,1) == REDISMODULE_ERR)
355	        return REDISMODULE_ERR;
356	
357	    if (RedisModule_CreateCommand(ctx,"hellotype.brange",
358	        HelloTypeBRange_RedisCommand,"readonly",1,1,1) == REDISMODULE_ERR)
359	        return REDISMODULE_ERR;
360	
361	    return REDISMODULE_OK;
362	}
