/* HELLOTYPE.SUM key -- Return the sum of all the elements in the list, or 0
 * if the key does not exist or holds an empty list. */
int HelloTypeSum_RedisCommand(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
    RedisModule_AutoMemory(ctx); /* Use automatic memory management. */

    if (argc != 2) return RedisModule_WrongArity(ctx);
    RedisModuleKey *key = RedisModule_OpenKey(ctx,argv[1],
        REDISMODULE_READ|REDISMODULE_WRITE);
    int type = RedisModule_KeyType(key);
    if (type != REDISMODULE_KEYTYPE_EMPTY &&
        RedisModule_ModuleTypeGetType(key) != HelloType)
    {
        return RedisModule_ReplyWithError(ctx,REDISMODULE_ERRORMSG_WRONGTYPE);
    }

    struct HelloTypeObject *hto = RedisModule_ModuleTypeGetValue(key);
    RedisModule_ReplyWithLongLong(ctx,hto ? HelloTypeSum(hto) : 0);
    return REDISMODULE_OK;
}

/* HELLOTYPE.REMOVE key value -- Remove a single element matching 'value',
 * replying 1 if an element was removed and 0 otherwise. */
int HelloTypeRemove_RedisCommand(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
    RedisModule_AutoMemory(ctx); /* Use automatic memory management. */

    if (argc != 3) return RedisModule_WrongArity(ctx);
    RedisModuleKey *key = RedisModule_OpenKey(ctx,argv[1],
        REDISMODULE_READ|REDISMODULE_WRITE);
    int type = RedisModule_KeyType(key);
    if (type != REDISMODULE_KEYTYPE_EMPTY &&
        RedisModule_ModuleTypeGetType(key) != HelloType)
    {
        return RedisModule_ReplyWithError(ctx,REDISMODULE_ERRORMSG_WRONGTYPE);
    }

    long long value;
    if ((RedisModule_StringToLongLong(argv[2],&value) != REDISMODULE_OK)) {
        return RedisModule_ReplyWithError(ctx,"ERR invalid value: must be a signed 64 bit integer");
    }

    struct HelloTypeObject *hto = RedisModule_ModuleTypeGetValue(key);
    int removed = hto ? HelloTypeRemove(hto,value) : 0;

    if (removed) {
        /* Don't leave an empty value around: deleting the key keeps both the
         * RDB and the AOF representation consistent with an empty list. */
        if (hto->len == 0) RedisModule_DeleteKey(key);
        RedisModule_ReplicateVerbatim(ctx);
    }

    RedisModule_ReplyWithLongLong(ctx,removed);
    return REDISMODULE_OK;
}

